k<ActionResult<IEnumerable<clReadTicketsUsuariosAsignados>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? ticketsUsuariosAsignadosID,            [FromQuery] int? ticketID,            [FromQuery] string? tituloTicket,            [FromQuery] int? usuarioID,            [FromQuery] string? usuarioAsignado,            [FromQuery] bool? terminado,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetTicketsUsuariosAsignadosDynamic(                ticketsUsuariosAsignadosID,                 ticketID,                 tituloTicket,                 usuarioID,                 usuarioAsignado,                 terminado,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo TicketsUsuariosAsignado.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del TicketsUsuariosAsignado a crear.</param>        /// <returns>El TicketsUsuariosAsignado recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear TicketsUsuariosAsignados",            Description = "Inserta un nuevo TicketsUsuariosAsignado en la base de datos."        )]        [ProducesResponseType(typeof(clReadTicketsUsuariosAsignados), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadTicketsUsuariosAsignados>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateTicketsUsuariosAsignados objInput)        {            var vCreated = await _objService.CreateTicketsUsuariosAsignados(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de TicketsUsuariosAsignado.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del TicketsUsuariosAsignado.</param>        /// <returns>El TicketsUsuariosAsignado actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar TicketsUsuariosAsignados",            Description = "Actualiza uno o varios campos de TicketsUsuariosAsignado existente."        )]        [ProducesResponseType(typeof(clReadTicketsUsuariosAsignados), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadTicketsUsuariosAsignados>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateTicketsUsuariosAsignados objInput)        {            var vUpdated = await _objService.UpdateTicketsUsuariosAsignados(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un TicketsUsuariosAsignado por su ID.        /// </summary>        [HttpDelete("{nTicketsUsuariosAsignadosID:int}")]        [SwaggerOperation(            Summary = "Eliminar TicketsUsuariosAsignado",            Description = "Borra un TicketsUsuariosAsignado si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nTicketsUsuariosAsignadosID)        {            var success = await _objService.DeleteTicketsUsuariosAsignados(nTicketsUsuariosAsignadosID);            return success ? NoContent() : NotFound();        }    }}